    row_height = imgui__table_get_header_row_height(imgui_c89_ctx);
    imgui_table_next_row(imgui_c89_ctx, ImGuiTableRowFlags_Headers, row_height);
    row_y1 = imgui_c89_ctx->CurrentWindow->DC.CursorPos.y;
